mapper.select:
select count(*)
  from reservation
 where charger_id = #{chargerId}
   and status in ('예약완료', '인증완료', '충전중')
   and start_time < #{endTime}
   and end_time + interval '5 minutes' > #{startTime}

select count(*)
  from reservation
 where vehicle_id = #{vehicleId}
   and status in ('예약완료', '인증완료', '충전중')
   and start_time < #{endTime}
   and end_time + interval '5 minutes' > #{startTime}

mapper.insert:
insert into reservation (
      member_id
    , vehicle_id
    , charger_id
    , reservation_date
    , start_time
    , end_time
    , current_soc
    , target_soc
    , required_kwh
    , estimated_minutes
    , estimated_cost
    , auth_code
    , created_at
)
values (
      #{memberId}
    , #{vehicleId}
    , #{chargerId}
    , #{reservationDate}
    , #{startTime}
    , #{endTime}
    , #{currentSoc}
    , #{targetSoc}
    , #{requiredKwh}
    , #{estimatedMinutes}
    , #{estimatedCost}
    , #{authCode}
    , current_timestamp
)

mapper.update:
update reservation
   set auth_code = #{authCode},
       updated_at = current_timestamp
 where reservation_id = #{reservationId}
   and member_id = #{memberId}

update reservation
   set status = '완료'
     , updated_at = current_timestamp
 where reservation_id = #{reservationId}
   and member_id = #{memberId}
   and status = '충전중'

mapper.select:
select email
  from app_member
 where member_id = #{memberId}

select c.charger_id , c.station_id , c.charger_name , c.charger_type , c.connector_type , c.charging_speed_kw , c.price_per_kwh
, case /* * 충전소가 운영중이 아니면 충전기 시간 예약보다 충전소 운영 상태를 우선 표시한다. */ when cs.station_status <> '운영중' then cs.station_status
/* * 충전기 자체가 점검중/고장이면 예약 시간보다 장비 상태를 우선 표시한다. */ when c.status in ('점검중', '고장') then c.status
/* * 해당 시간대에 실제 충전중인 예약이 있으면 * 예약중이 아니라 사용중으로 표시한다. */ when exists ( select 1 from reservation r where r.charger_id = c.charger_id and r.status = '충전중' and r.start_time < #{endTime} and r.end_time + interval '5 minutes' > #{startTime} ) then '사용중'
/* * 아직 충전 시작 전이지만 해당 시간대를 점유하는 예약이면 * 예약중으로 표시한다. */ when exists ( select 1 from reservation r where r.charger_id = c.charger_id and r.status in ('예약완료', '인증완료') and r.start_time < #{endTime} and r.end_time + interval '5 minutes' > #{startTime} ) then '예약중'
/* * 겹치는 예약도 없고 고장/점검도 아니면 사용가능 */ else '사용가능' end as status
, case when exists ( select 1 from reservation r where r.charger_id = c.charger_id and r.status in ('예약완료', '인증완료', '충전중') and r.start_time < #{endTime} and r.end_time + interval '5 minutes' > #{startTime} ) or c.status in ('점검중', '고장') or cs.station_status <> '운영중' then true else false end as reserved
from charger c join charging_station cs on c.station_id = cs.station_id where c.station_id = #{stationId} order by case when cs.station_status <> '운영중' then 6 when c.status = '사용가능' then 1 when c.status = '예약중' then 2 when c.status = '사용중' then 3 when c.status = '점검중' then 4 when c.status = '고장' then 5 else 6 end , c.charger_id asc
